-- One encrypted Claude (Anthropic) profile per tenant, used for AI inventory extraction. The API also applies this idempotently at startup (ClaudeSchema).
CREATE TABLE IF NOT EXISTS "TenantClaudeConfigurations" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "EncryptedApiKey" varchar(1000) NOT NULL, "ApiKeyLastFour" varchar(4) NOT NULL, "ExtractionModel" varchar(120) NOT NULL, "Effort" varchar(20) NOT NULL, "InputPricePerMillion" numeric(18,6) NULL, "CachedInputPricePerMillion" numeric(18,6) NULL, "OutputPricePerMillion" numeric(18,6) NULL, "CreatedAtUtc" timestamp with time zone NOT NULL, "UpdatedAtUtc" timestamp with time zone NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_TenantClaudeConfigurations_Id" ON "TenantClaudeConfigurations"("Id");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_TenantClaudeConfigurations_Tenant" ON "TenantClaudeConfigurations"("TenantId");
